use xiom.io;

use xiom.string;
fn multiply_from_strings(a: Str, b: Str) -> Result[Int, Str] {
  let x = string.str_to_int(a)?;
  let y = string.str_to_int(b)?;
  return Ok(x * y);
}

fn add_three(a: Str, b: Str, c: Str) -> Result[Int, Str] {
  let x = string.str_to_int(a)?;
  let y = string.str_to_int(b)?;
  let z = string.str_to_int(c)?;
  return Ok(x + y + z);
}

fn main() -> Int {
  match multiply_from_strings("6", "7") {
    Ok(r) => io.println(to_string(r)),
    Err(e) => io.println("Error: " + e.to_str()),
  };
  match multiply_from_strings("6", "bad") {
    Ok(r) => io.println(to_string(r)),
    Err(e) => io.println("Error: " + e.to_str()),
  };
  match add_three("1", "2", "3") {
    Ok(r) => io.println(to_string(r)),
    Err(e) => io.println("Error: " + e.to_str()),
  };
  return 0;
}
